import asyncio
from sc2 import maps
from sc2.bot_ai import BotAI
from sc2.data import Race, Difficulty
from sc2.ids.unit_typeid import UnitTypeId
from sc2.ids.ability_id import AbilityId
from sc2.ids.upgrade_id import UpgradeId
from sc2.main import run_game
from sc2.player import Bot, Computer
from sc2.position import Point2

class ZergRushBot(BotAI):
    async def on_start(self):
        await self.client.game_step(2)
        self.rushed = False
        self.chat_sent = False

    async def on_step(self, iteration):
        # Send a chat message once at the start
        if not self.chat_sent:
            await self.chat_send("GLHF! Prepare for the Zerg rush!")
            self.chat_sent = True

        await self.inject_larva()
        await self.manage_resources()
        await self.research_upgrades()
        await self.train_units()
        await self.build_structures()
        await self.attack_enemy()
        await self.draw_creep_pixelmap()

    async def on_end(self, result):
        print(f"Game ended with result: {result}")

    async def inject_larva(self):
        for queen in self.units(UnitTypeId.QUEEN).idle:
            abilities = await self.get_available_abilities(queen)
            for hatch in self.townhalls.ready:
                if AbilityId.EFFECT_INJECTLARVA in abilities and queen.energy >= 25:
                    if queen.distance_to(hatch) < 8:
                        queen(AbilityId.EFFECT_INJECTLARVA, hatch)
                        break

    async def manage_resources(self):
        # Build Extractors if we have less than 2 and enough drones
        if self.townhalls.ready.exists and self.units(UnitTypeId.DRONE).amount > 14:
            for hatch in self.townhalls.ready:
                vgs = self.vespene_geyser.closer_than(10, hatch)
                for vg in vgs:
                    if self.can_afford(UnitTypeId.EXTRACTOR) and not self.gas_buildings.closer_than(1, vg).exists:
                        drone = self.select_build_worker(vg.position)
                        if drone:
                            drone.build(UnitTypeId.EXTRACTOR, vg)
                            return

        # Distribute workers
        await self.distribute_workers()

    async def research_upgrades(self):
        # Research Zergling Speed
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready.exists:
            pool = self.structures(UnitTypeId.SPAWNINGPOOL).ready.first
            if self.can_afford(UpgradeId.ZERGLINGMOVEMENTSPEED) and not self.already_pending_upgrade(UpgradeId.ZERGLINGMOVEMENTSPEED):
                abilities = await self.get_available_abilities(pool)
                if AbilityId.RESEARCH_ZERGLINGMETABOLICBOOST in abilities:
                    pool(AbilityId.RESEARCH_ZERGLINGMETABOLICBOOST)

    async def train_units(self):
        # Train Zerglings
        for hatch in self.townhalls.ready.idle:
            if self.can_afford(UnitTypeId.ZERGLING) and self.supply_left > 0:
                hatch.train(UnitTypeId.ZERGLING)

        # Train Queens if we have less than 2
        if self.structures(UnitTypeId.SPAWNINGPOOL).ready.exists:
            for hatch in self.townhalls.ready:
                if self.units(UnitTypeId.QUEEN).amount < 2 and self.can_afford(UnitTypeId.QUEEN):
                    if hatch.is_idle:
                        hatch.train(UnitTypeId.QUEEN)

        # Train Overlords if supply is low
        if self.supply_left < 2 and self.can_afford(UnitTypeId.OVERLORD):
            for hatch in self.townhalls.ready.idle:
                hatch.train(UnitTypeId.OVERLORD)

    async def build_structures(self):
        # Build Spawning Pool if we don't have one
        if not self.structures(UnitTypeId.SPAWNINGPOOL).exists and self.can_afford(UnitTypeId.SPAWNINGPOOL):
            pos = await self.get_next_expansion()
            if pos:
                placement = await self.find_placement(UnitTypeId.SPAWNINGPOOL, near=pos, placement_step=3)
                if placement:
                    drone = self.select_build_worker(placement)
                    if drone:
                        drone.build(UnitTypeId.SPAWNINGPOOL, placement)

        # Build additional Hatchery if we have enough minerals and drones
        if self.townhalls.amount < 2 and self.can_afford(UnitTypeId.HATCHERY) and self.units(UnitTypeId.DRONE).amount > 18:
            pos = await self.get_next_expansion()
            if pos:
                drone = self.select_build_worker(pos)
                if drone:
                    drone.build(UnitTypeId.HATCHERY, pos)

    async def attack_enemy(self):
        # Attack enemy structures with all Zerglings if we have at least 18
        if self.units(UnitTypeId.ZERGLING).amount >= 18:
            target = self.enemy_structures.random_or(self.enemy_start_locations[0])
            for zergling in self.units(UnitTypeId.ZERGLING).idle:
                zergling.attack(target.position)
            self.rushed = True
        elif self.rushed:
            # Continue attacking with any new Zerglings
            target = self.enemy_structures.random_or(self.enemy_start_locations[0])
            for zergling in self.units(UnitTypeId.ZERGLING).idle:
                zergling.attack(target.position)

    async def draw_creep_pixelmap(self):
        # Draw creep pixelmap for debugging
        creep_map = self.state.creep.data_numpy
        for y in range(0, creep_map.shape[0], 8):
            for x in range(0, creep_map.shape[1], 8):
                if creep_map[y][x]:
                    pos = Point2((x, y))
                    self._client.debug_box2_out(pos, pos + Point2((1, 1)), color=(0, 255, 0))

if __name__ == "__main__":
    run_game(
        maps.get("AcropolisLE"),
        [
            Bot(Race.Zerg, ZergRushBot()),
            Computer(Race.Terran, Difficulty.Medium)
        ],
        realtime=False,
        save_replay_as="zerg_rush_bot.SC2Replay"
    )
